H,W=19,16
seeds=[(2,2,1),(4,4,6),(4,14,1),(6,6,6),(7,14,6),(10,10,1),(15,2,6),(17,9,1)]
g=[[4]*W for _ in range(H)]
for r,c,v in seeds:g[r][c]=v
# Same-color 1 endpoints on a diagonal connect along the segment only.
for i,(r,c,v) in enumerate(seeds):
 if v!=1: continue
 for rr,cc,vv in seeds[i+1:]:
  if vv==1 and abs(rr-r)==abs(cc-c):
   dr=1 if rr>r else -1; dc=1 if cc>c else -1
   for k in range(1,abs(rr-r)):
    if g[r+dr*k][c+dc*k]==4:g[r+dr*k][c+dc*k]=1
# A repeated color-6 diagonal pair is a stroke continuing to board boundaries.
for i,(r,c,v) in enumerate(seeds):
 if v!=6:continue
 for rr,cc,vv in seeds[i+1:]:
  if vv==6 and rr-r==cc-c and rr!=r:
   # extend the pair's NW-SE diagonal to its boundaries
   for k in range(-min(r,c),min(H-1-r,W-1-c)+1):
    if g[r+k][c+k]==4:g[r+k][c+k]=6
# preserve every seed
for r,c,v in seeds:g[r][c]=v
print('\n'.join(' '.join(map(str,row)) for row in g))
